//! `xmlsec/version.h`: the version of libxmlsec1 the headers are, as
//! `xmlSecCheckVersionExt` compares a caller's against. Generated by
//! `xml-sec-tools xmlsec1-headers`; edits are overwritten.

/// `XMLSEC_VERSION_MAJOR`, `XMLSEC_VERSION_MINOR`, `XMLSEC_VERSION_SUBMINOR`.
pub(crate) const VERSION: (core::ffi::c_int, core::ffi::c_int, core::ffi::c_int) = (1, 3, 14);
